const backendScenarios = {
    "Node.js": {
        hints: ["Identify the Node runtime boundary: event loop, stream, process, or module lifecycle.", "Handle backpressure and process errors deliberately; do not turn operational failures into false success."],
        items: [
            ["Easy", "Read a configuration value safely", "A Node service requires PORT and a default when it is absent. Parse the environment string as a positive integer, reject malformed or out-of-range values, and avoid logging the entire process.env object.", "PORT='5000' returns 5000; an absent PORT uses the documented default 3000.", "PORT='abc', '0', or '70000' is rejected before the server listens.", "function readPort(env) { if (env.PORT == null || env.PORT === '') return 3000; if (!/^[0-9]+$/.test(env.PORT)) throw new Error('Invalid PORT'); const port = Number(env.PORT); if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('Invalid PORT'); return port; }"],
            ["Easy", "Create a line-oriented Node stream", "Implement a Node.js Transform stream that receives UTF-8 text chunks split arbitrarily and emits each complete non-empty line with a line number. A line may cross chunk boundaries, and the final unterminated line must be emitted at stream end.", "Chunks 'red\\nb' and 'lue\\n' emit lines 1 red and 2 blue.", "An empty final buffer adds no phantom record.", "class LineNumberer extends Transform { constructor() { super(); this.buffer = ''; this.line = 0; } _transform(chunk, encoding, callback) { this.buffer += chunk.toString('utf8'); const parts = this.buffer.split('\\n'); this.buffer = parts.pop(); for (const text of parts) if (text) this.push(`${++this.line}: ${text}\\n`); callback(); } _flush(callback) { if (this.buffer) this.push(`${++this.line}: ${this.buffer}\\n`); callback(); } }", "Keep a carry-over buffer because chunk boundaries do not align with lines.", "Decode Buffer chunks explicitly, emit complete lines in _transform, and flush the remainder once in _flush."],
            ["Medium", "Respect writable-stream backpressure", "A Node endpoint streams a generated CSV to a client. Fix a loop that calls writable.write for every row without checking its return value; pause the producer until drain and stop cleanly if the client disconnects.", "Rows are emitted in order without unbounded buffering when write returns false.", "A close event prevents more rows from being produced.", "async function writeRows(writable, rows) { try { await pipeline(Readable.from(rows.map((row) => `${row.join(',')}\\n`)), writable); } catch (error) { if (!writable.destroyed) writable.destroy(error); throw error; } }", "Node's pipeline coordinates backpressure across readable and writable streams.", "Use pipeline so premature close and stream errors reject the operation instead of leaving a wait for drain hanging."],
            ["Medium", "Bound concurrent file hashing", "A Node import job hashes thousands of files. Implement a worker pool that processes at most four files concurrently, preserves each result with its source path, and stops scheduling new files after the first fatal filesystem error.", "Peak active hash calls never exceeds four and results identify their files.", "An empty path list resolves to an empty result; a rejected hash prevents later unscheduled work.", "async function hashFiles(paths, hashFile, limit = 4) { const results = new Array(paths.length); let next = 0; let failed = false; async function worker() { while (!failed) { const index = next++; if (index >= paths.length) return; try { results[index] = { path: paths[index], hash: await hashFile(paths[index]) }; } catch (error) { failed = true; throw error; } } } await Promise.all(Array.from({ length: Math.min(limit, paths.length) }, worker)); return results; }", "Use a fixed number of workers rather than launching one promise per path.", "Allocate result positions by input index so completion timing does not reorder files."],
            ["Hard", "Stream a large upload through a size guard", "A Node API proxies an uploaded stream to private storage. Enforce a byte cap while streaming, stop the upstream write immediately when exceeded, and ensure a client disconnect or storage error cleans up the partial object.", "A stream under the limit completes and finalizes the object.", "A limit + 1 byte aborts storage and removes the partial object.", "async function copyBounded(source, destination, maxBytes, removePartial) { let bytes = 0; try { for await (const chunk of source) { bytes += chunk.length; if (bytes > maxBytes) throw new RangeError('Upload too large'); if (!destination.write(chunk)) await once(destination, 'drain'); } destination.end(); await finished(destination); } catch (error) { source.destroy(); destination.destroy(); await removePartial(); throw error; } }", "Count actual bytes in each chunk rather than trusting multipart metadata.", "Put cleanup in the failure path and await writable completion before reporting success."],
            ["Hard", "Shut down a Node server gracefully", "Implement a shutdown routine that stops accepting HTTP requests, waits up to a deadline for active requests and database work, closes the database connection, and then exits. If the deadline expires, log a sanitized warning and force termination.", "A normal SIGTERM drains active requests before the database closes.", "A hung request cannot keep the process alive beyond the configured deadline.", "async function shutdown(server, database, deadlineMs) { const timeout = setTimeout(() => { logger.warn('Graceful shutdown deadline exceeded'); process.exitCode = 1; server.closeAllConnections?.(); }, deadlineMs); try { await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve())); await database.close(); clearTimeout(timeout); } catch (error) { logger.error({ name: error.name }, 'Shutdown failed'); process.exitCode = 1; } }", "Stop accepting new connections first, then wait for the server close callback.", "Bound the wait, set process.exitCode, and let normal cleanup run instead of exiting before resources can flush."],
        ]
    },
    NPM: {
        hints: ["Treat package.json as the project's executable contract and lockfile as the resolved dependency record.", "Use reproducible install and audit commands; never hide lifecycle or version drift."],
        items: [
            ["Easy", "Add a repeatable development script", "A Node API team runs node server.js manually with different working directories. Define an npm script that starts the same entry file consistently and document which package directory owns the script.", "npm run start invokes the intended server entry from the package root.", "Running the command from another directory after selecting the package still resolves the expected relative entry.", "{\n  \"scripts\": {\n    \"start\": \"node server.js\"\n  }\n}\nRun with npm --prefix server run start when invoking from the repository root.", "Place scripts in the package that owns the entry file.", "Use npm's package context instead of relying on an accidental shell working directory."],
            ["Easy", "Separate runtime and development dependencies", "A server imports express in production but imports nodemon only for local development. Move each dependency into the correct package.json section and explain what a production-only install retains.", "express is a dependency and nodemon is a devDependency.", "The production start script does not require nodemon.", "{\n  \"dependencies\": { \"express\": \"<approved-range>\" },\n  \"devDependencies\": { \"nodemon\": \"<approved-range>\" }\n}", "Classify by whether the application needs the package at runtime.", "Do not copy guessed versions; use versions resolved and reviewed for this project."],
            ["Medium", "Reproduce a lockfile-based install", "A CI build works on one developer's machine but resolves different transitive packages elsewhere. Specify the npm command and repository artifacts needed for deterministic installation, and identify what should happen if package.json and package-lock.json disagree.", "CI uses npm ci with the committed lockfile and fails on inconsistent manifests.", "CI does not silently regenerate or commit a new lockfile during the build.", "# Commit package.json and package-lock.json together.\nnpm ci\nnpm run build", "Use npm ci in automated environments because it installs exactly the lockfile graph.", "Treat a mismatch as a dependency change to review, not a build-time mutation."],
            ["Medium", "Add a non-destructive dependency audit step", "Add an npm audit check to CI for a Node service. Define how findings are reviewed and why automatically running npm audit fix --force can introduce breaking upgrades.", "CI reports vulnerabilities for triage without rewriting dependencies automatically.", "A breaking major upgrade is handled through a reviewed change rather than an unattended fix.", "# CI check (review policy determines whether findings fail the build)\nnpm audit --omit=dev", "Choose production scope deliberately and inspect advisory paths and fixed versions.", "Do not use an automatic force upgrade as a substitute for compatibility review."],
            ["Hard", "Plan a controlled dependency upgrade", "An Express major release is available while the application has middleware and route tests. Create an upgrade sequence that records current versions, reads migration notes, updates one package set, runs tests/build, and produces a reviewed lockfile diff.", "The change is reproducible and verified against existing routes and middleware behavior.", "A failed test stops rollout and leaves the main branch dependency set unchanged.", "git switch -c chore/express-upgrade\nnpm install express@<reviewed-version>\nnpm test\nnpm run build\ngit diff -- package.json package-lock.json", "Read the official migration guide and identify API removals before changing versions.", "Keep dependency and lockfile edits reviewable and run the test suite before merging."],
            ["Hard", "Diagnose an install script supply-chain risk", "A transitive package adds a postinstall script that downloads an executable from an unpinned URL. Assess the risk and propose a safe investigation and mitigation path without running the script or logging credentials.", "The team inspects the package provenance, script, integrity metadata, and dependency path before deciding to upgrade, replace, or remove it.", "Disabling scripts globally without understanding native build requirements is not assumed safe.", "# Safe review steps\nnpm explain package-name\nnpm view package-name scripts dist.integrity\n# Inspect the lockfile and package source before deciding on a reviewed remediation.", "Trace why the dependency exists and inspect the exact script behavior first.", "Record a pinned, reviewed remediation and verify the app still installs and works."],
        ]
    },
    "Express.js": {
        hints: ["Express middleware order determines which parsed, authenticated, and validated values a handler receives.", "Always finish a request once, preserve route contracts, and test status plus response shape."],
        items: [
            ["Easy", "Create a health route without exposing internals", "Add an Express GET /health endpoint returning a small JSON readiness response. Do not return environment variables, database connection strings, or detailed process information.", "GET /health returns 200 with {success:true,data:{status:'ok'}}.", "A database secret is never present in the response.", "app.get('/health', (req, res) => res.status(200).json({ success: true, data: { status: 'ok' } }));", "Keep liveness output minimal and stable.", "Return only the fields clients or monitoring actually need."],
            ["Easy", "Parse JSON before a route reads req.body", "An Express POST /projects handler receives undefined req.body. Put the JSON parser at the correct application level and ensure it runs before the route while preserving the existing response contract.", "A valid JSON request reaches the controller as an object.", "Malformed JSON is rejected with a client error before controller logic runs.", "app.use(express.json({ limit: '100kb' }));\napp.use('/api/projects', projectRoutes);", "Application middleware executes in registration order.", "Register the parser before route mounting and select a deliberate body-size limit."],
            ["Medium", "Keep request logging useful and private", "Add an Express request logger that records method, path, status, duration, and a request ID, but does not log query-string secrets, Authorization headers, or request bodies.", "A request to /search?q=private logs /search and method/status/timing only.", "A bearer token and submitted document text never appear in logs.", "app.use((req, res, next) => { const started = Date.now(); const requestId = crypto.randomUUID(); res.setHeader('X-Request-Id', requestId); res.on('finish', () => logger.info({ requestId, method: req.method, path: req.path, status: res.statusCode, durationMs: Date.now() - started })); next(); });", "Log the pathname rather than originalUrl when query values may be sensitive.", "Record completion from the response finish event and include only safe diagnostic fields."],
            ["Medium", "Use one response path for async handlers", "An Express controller awaits a service but a rejection becomes an unhandled promise in the current setup. Add an async wrapper or explicit try/catch that forwards the error to centralized middleware exactly once.", "A successful call returns its expected JSON response.", "A rejected service call reaches the error handler and does not attempt a second response.", "const asyncHandler = (handler) => (req, res, next) => Promise.resolve(handler(req, res, next)).catch(next);\nrouter.get('/:id', asyncHandler(async (req, res) => { const item = await service.get(req.params.id); return res.json({ success: true, data: item }); }));", "Pick one established async error-forwarding convention and apply it consistently.", "Return the promise chain so the wrapper can catch rejection and call next once."],
            ["Hard", "Mount routers without shadowing static routes", "An Express app mounts /:id before /search, so GET /search is interpreted as an ID. Reorder routes and validate the ID in middleware so the solution works across supported Express router versions.", "GET /search reaches the search handler and GET /:id reaches the record handler.", "An invalid record ID returns a controlled client error and does not fall through into a different route accidentally.", "router.get('/search', searchController);\nrouter.get('/:id', validateObjectId, detailController);", "More specific static paths should be registered before broad parameter paths.", "Keep ID validation in middleware rather than relying on version-specific inline path syntax."],
            ["Hard", "Build centralized Express error middleware", "Create the final Express error handler that preserves explicit 4xx validation errors, logs sanitized diagnostics for unexpected failures, and returns a generic 500 message without stack traces or raw database messages.", "A known validation error keeps its 400 status and safe message.", "An unexpected error returns 500 Internal server error while logs omit request body and credentials.", "function errorHandler(error, req, res, next) { if (res.headersSent) return next(error); const status = Number.isInteger(error.status) && error.status >= 400 && error.status < 500 ? error.status : 500; if (status === 500) logger.error({ requestId: req.id, name: error.name, code: error.code }, 'Request failed'); return res.status(status).json({ success: false, message: status === 500 ? 'Internal server error' : error.message }); }", "Check headersSent before writing and allow Express's final handler to manage an already-started response.", "Log only sanitized metadata for unexpected failures and keep server internals out of the response."],
        ]
    },
    Routing: {
        hints: ["A route is a method plus a path and ordered middleware; route specificity and parameter parsing matter.", "Test path boundaries, ownership inputs, and consistent not-found behavior."],
        items: [
            ["Easy", "Define collection and detail paths", "Design Express routes for listing projects and reading one project by ID. Keep collection and item paths consistent and use the correct HTTP method without placing the ID in a query parameter.", "GET /api/projects lists; GET /api/projects/p-1 reads one record.", "POST /api/projects/p-1 is not accidentally treated as a read route.", "router.get('/projects', listProjects);\nrouter.get('/projects/:id', getProject);", "Separate collection and item resources by the path segment and HTTP method.", "Keep the route declaration thin and delegate behavior to the matching controller."],
            ["Easy", "Reject malformed route identifiers", "An Express detail route expects a MongoDB ObjectId. Validate the path parameter before querying and return the API's safe 400 or 404 policy consistently instead of leaking a cast exception.", "A valid 24-hex ID reaches the query.", "A malformed ID returns a client-safe response and does not issue a database query.", "router.get('/:id', (req, res, next) => { if (!/^[a-f0-9]{24}$/i.test(req.params.id)) return res.status(400).json({ success: false, message: 'Invalid id' }); return next(); }, detailController);", "Validate at the route boundary before constructing a database query.", "Use a response policy consistent with the rest of the API and stop the pipeline after responding."],
            ["Medium", "Support optional filters without route ambiguity", "Add a GET /projects/search route with role and location query filters while a detail route /projects/:id also exists. Ensure /search is handled as a static route and scalar query values are validated.", "GET /projects/search?role=Engineer reaches search.", "Repeated role parameters are rejected rather than silently converted to an array.", "router.get('/projects/search', validateSearchQuery, searchProjects);\nrouter.get('/projects/:id', validateId, getProject);", "Static routes should be declared before broad parameter routes.", "Validate query shape before passing it to the service."],
            ["Medium", "Add a nested user-owned resource route", "Design GET /users/me/projects/:projectId using the authenticated identity already on req.user. Do not accept an arbitrary owner ID in the path or body for this self-service endpoint.", "The service receives req.user.id and projectId.", "Changing a client-supplied userId cannot read another account's project.", "router.get('/users/me/projects/:projectId', requireAuth, (req, res, next) => projectController.getOwned(req, res, next));\n// controller/service predicate: { _id: req.params.projectId, user: req.user.id }", "The 'me' route segment signals identity comes from the verified session.", "Put the owner predicate in the database query, not only in the response formatting."],
            ["Hard", "Design idempotent route behavior", "A mobile client may retry POST /api/projects after a network timeout even if the first create succeeded. Define an idempotency-key contract, storage scope, response replay, and expiry so retries do not create duplicate projects.", "The same owner and key replay the original successful result.", "The same key used by another owner cannot retrieve the first owner's response.", "router.post('/projects', requireAuth, validateIdempotencyKey, createProject);\n// Unique key scope includes authenticated owner; persist request hash and completed response before replay.", "Scope the idempotency key by authenticated owner and compare a request hash.", "Persist completion atomically enough to distinguish in-progress from completed retries."],
            ["Hard", "Prevent route-level privilege bypass", "An API has admin routes nested under /api/admin and a public route with a similar controller. Specify route mounting and middleware order so every admin path is authenticated and role-checked, including newly added child routes.", "Every /api/admin route passes requireAuth and requireAdmin before handlers.", "A newly added admin child route cannot be mounted outside the protected router by convention alone.", "const adminRouter = express.Router();\nadminRouter.use(requireAuth, requireAdmin);\nadminRouter.get('/reports', reportController);\napp.use('/api/admin', adminRouter);", "Apply authorization to the router before registering its child endpoints.", "Keep the protected router as the only mount point for admin controllers."],
        ]
    },
    Middleware: {
        hints: ["Middleware runs in order and must either finish the response or pass control exactly once.", "Keep cross-cutting concerns small, ordered, and explicit about what they attach to req or res."],
        items: [
            ["Easy", "Add a request ID to each request", "Write Express middleware that assigns a UUID to req.id, returns the same value in X-Request-Id, and calls next exactly once. Do not accept the ID from an untrusted query value.", "The controller and response header see the same generated request ID.", "Two requests receive different IDs, even if the caller sends ?id=chosen.", "function requestId(req, res, next) { req.id = crypto.randomUUID(); res.setHeader('X-Request-Id', req.id); return next(); }", "Create the correlation ID in trusted middleware before logging and route handlers.", "Use the same server-generated value for both req and response diagnostics."],
            ["Easy", "Stop a request after validation fails", "Implement middleware that requires a scalar non-empty title string in req.body. On invalid input, return a 400 JSON response and do not call next; otherwise call next once.", "A trimmed non-empty title reaches the controller.", "An array, object, missing title, or whitespace-only title receives 400 and never reaches the controller.", "function requireTitle(req, res, next) { const title = req.body?.title; if (typeof title !== 'string' || !title.trim()) return res.status(400).json({ success: false, message: 'Title is required' }); req.validatedTitle = title.trim(); return next(); }", "Reject non-scalar values before trimming so arrays do not pass through coercion.", "Attach the normalized value and let the controller consume that trusted result."],
            ["Medium", "Order parsing, authentication, and validation", "An authenticated JSON endpoint needs req.body, req.user, and validated data. Arrange the app and route middleware so body parsing happens before auth-dependent validation and the controller runs last.", "The controller sees parsed data and a verified identity only after all checks pass.", "Malformed JSON stops before the controller; missing auth stops before protected validation or business logic.", "app.use(express.json({ limit: '100kb' }));\nrouter.post('/projects', requireAuth, validateProject, createProject);\napp.use('/api', router);", "Application-level parsing must be registered before routes that read req.body.", "Within the route, authenticate and validate before the controller performs side effects."],
            ["Medium", "Add a rate limit key that respects identity", "A login endpoint needs a rate limit based on client IP and normalized account identifier. Design middleware that does not trust an arbitrary forwarded-for header unless the proxy configuration is trusted, and avoids logging the submitted password.", "Repeated attempts for one IP/account pair are bounded.", "A forged X-Forwarded-For header does not bypass limits when the proxy is untrusted.", "function loginLimitKey(req) { const ip = req.ip; const email = typeof req.body?.email === 'string' ? req.body.email.trim().toLowerCase() : ''; return `${ip}:${email}`; }\n// Configure Express trust proxy only for known proxy hops before relying on req.ip.", "Understand Express trust proxy settings before using forwarded address headers.", "Include an account dimension carefully and keep credentials out of the key and logs."],
            ["Hard", "Propagate async middleware failures once", "An async middleware reads a user session and may reject. Wrap it so the rejection reaches centralized error middleware exactly once while a deliberate 401 response does not continue down the pipeline.", "A valid session calls next; an invalid session sends 401 and stops.", "A session-store rejection reaches the error handler and does not cause an unhandled rejection or a second response.", "const asyncMiddleware = (middleware) => (req, res, next) => Promise.resolve(middleware(req, res, next)).catch(next);\nconst requireSession = asyncMiddleware(async (req, res, next) => { const user = await sessionStore.find(req); if (!user) return res.status(401).json({ success: false, message: 'Authentication required' }); req.user = user; return next(); });", "Return the async middleware promise from the wrapper so rejection can be forwarded.", "After sending a response, return immediately and do not call next."],
            ["Hard", "Prevent double response from timeout middleware", "A timeout middleware sends 504 after a deadline while the controller may later resolve and attempt 200. Design cancellation or response-state coordination so only one response is written and expensive work is stopped when possible.", "A timed-out request receives one 504 and no later success write.", "A response that completes before the deadline clears its timer.", "function withDeadline(handler, milliseconds) { return async (req, res, next) => { const controller = new AbortController(); req.signal = controller.signal; const timer = setTimeout(() => { if (!res.headersSent) { controller.abort(); res.status(504).json({ success: false, message: 'Request timed out' }); } }, milliseconds); try { await handler(req, res, next); } catch (error) { if (!res.headersSent) next(error); } finally { clearTimeout(timer); } }; }", "A timer alone cannot stop underlying work; pass an abort signal where the operation supports it.", "Before writing a timeout or error response, check whether headers have already been sent."],
        ]
    },
    "REST APIs": {
        hints: ["Design around resource contracts, HTTP semantics, bounded inputs, and stable response envelopes.", "Consider retries, concurrency, errors, and client compatibility as part of the endpoint contract."],
        items: [
            ["Easy", "Return a consistent collection envelope", "Design GET /api/skills to return a JSON success envelope with data as an array, including when there are no skills. Keep metadata separate from the collection so existing array consumers remain predictable.", "An empty collection returns {success:true,data:[]}.", "The endpoint never returns null or an object in place of data array.", "return res.status(200).json({ success: true, data: skills }); // data is always an array, including [].", "Keep the collection type stable for zero and non-zero results.", "Use the same response shape across list and empty cases."],
            ["Easy", "Use status codes for create and missing resources", "Specify HTTP responses for creating a project and requesting an unknown project ID. Include the response body envelope and ensure a failed lookup is not a successful 200 with null.", "A successful create returns 201 with the created record; absent ID returns 404.", "A validation failure returns 400 and no record is created.", "res.status(201).json({ success: true, data: createdProject });\n// missing resource\nres.status(404).json({ success: false, message: 'Project not found' });", "Use status codes to distinguish creation, validation, and absence.", "Keep success and failure envelopes consistent with the existing API convention."],
            ["Medium", "Specify bounded pagination and deterministic order", "Design a GET /api/activities contract with page and limit defaults, a maximum page size, repeated-parameter rejection, stable newest-first ordering, and pagination metadata while keeping data an array.", "A valid page returns at most the capped limit and stable ordering for equal timestamps.", "page[]=2, zero, and negative values return 400 before the query.", "const page = parsePositiveInt(req.query.page, 1); const limit = Math.min(parsePositiveInt(req.query.limit, 10), 50); const data = await Activity.find(filter).sort({ createdAt: -1, _id: -1 }).skip((page - 1) * limit).limit(limit); res.json({ success: true, data, pagination: { page, limit, total } });", "Validate scalar query shape before integer conversion and cap limit before querying.", "Add a unique tie-breaker to sort and keep the existing response envelope."],
            ["Medium", "Make PATCH updates allowlisted", "A REST PATCH endpoint updates a project but currently spreads req.body directly onto a MongoDB document. Define an allowlist of editable fields, preserve ownership fields, and distinguish an omitted field from an explicit empty string.", "Only title and description can change; user and createdAt remain unchanged.", "An attempted role or ownerId update is rejected or ignored according to the API contract.", "const allowed = ['title', 'description']; const patch = Object.fromEntries(Object.entries(req.body).filter(([key]) => allowed.includes(key))); const updated = await Project.findOneAndUpdate({ _id: req.params.id, user: req.user.id }, { $set: patch }, { new: true, runValidators: true });", "Build the update object from an explicit field allowlist.", "Include authenticated ownership in the query and run model validators."],
            ["Hard", "Make a create endpoint safe for client retries", "A create request may reach the server twice after a timeout. Design idempotency semantics, key validation, owner scoping, request-hash conflict behavior, and replay of the original response without duplicating the resource.", "Same owner/key/body returns the same created result on retry.", "Same owner/key with a different request body returns a conflict rather than replaying unrelated data.", "// Store a unique (ownerId, idempotencyKey) record with requestHash and response.\nif (existing && existing.requestHash !== requestHash) return res.status(409).json({ success: false, message: 'Idempotency key reused' });\nif (existing?.response) return res.status(existing.status).json(existing.response);", "Persist the key with its owner and a hash of the normalized request.", "A duplicate key is a replay only when the normalized request matches exactly."],
            ["Hard", "Evolve a REST response without breaking consumers", "A project response needs a new nested owner summary while old clients read ownerName. Design a compatibility period and tests for old and new clients; do not change the type or remove the old field immediately.", "Both shapes coexist until telemetry shows supported consumers have migrated.", "An old client still receives ownerName as a string during the transition.", "const response = { ...project, ownerName: owner.name, owner: { id: owner.id, name: owner.name } };\n// Document deprecation, monitor field use, then remove only after the published support window.", "Treat response fields as a public contract with independently deployed clients.", "Add contract tests for both client shapes before scheduling removal."],
        ]
    },
    Controllers: {
        hints: ["Keep controllers responsible for HTTP input/output while services own reusable business operations.", "Use authenticated identity and validated input; choose status and response envelope deliberately."],
        items: [
            ["Easy", "Return a created resource from the controller", "Write an Express createProject controller that reads validated title and description, gets owner ID from req.user, calls the project service once, and returns 201 with the established success envelope.", "A successful service result appears in data with status 201.", "The controller ignores a client-supplied ownerId field.", "async function createProject(req, res, next) { try { const project = await projectService.create({ title: req.validated.title, description: req.validated.description, userId: req.user.id }); return res.status(201).json({ success: true, data: project }); } catch (error) { return next(error); } }", "Use the trusted request identity rather than owner information in req.body.", "Return the created record and correct HTTP status without duplicate service calls."],
            ["Easy", "Map a missing service result to 404", "Implement a project detail controller that calls projectService.getOwned with the route ID and authenticated owner ID. If the service returns null, send the safe not-found envelope; otherwise preserve the normal success response.", "An owned project returns 200 and the expected data envelope.", "A missing or other-user project returns 404 without revealing ownership details.", "async function getProject(req, res, next) { try { const project = await projectService.getOwned(req.params.id, req.user.id); if (!project) return res.status(404).json({ success: false, message: 'Project not found' }); return res.json({ success: true, data: project }); } catch (error) { return next(error); } }", "Keep ownership in the service query and map the not-found result to one safe response.", "Do not return 200 with null or expose a cross-user existence distinction."],
            ["Medium", "Preserve validation status and hide internal errors", "A controller catches all errors and returns 500, including known request validation errors. Map expected validation errors to 400 while forwarding unknown failures to centralized middleware for sanitized logging.", "A known ValidationError returns 400 with safe message.", "A database error does not expose error.message to the client.", "async function updateProject(req, res, next) { try { const data = await projectService.update(req.params.id, req.user.id, req.validated); return res.json({ success: true, data }); } catch (error) { if (error.name === 'ValidationError') return res.status(400).json({ success: false, message: error.message }); return next(error); } }", "Catch only the expected error class the controller can translate.", "Let the shared error handler sanitize diagnostics for unexpected failures."],
            ["Medium", "Keep controllers thin with a service boundary", "A controller builds a complex query, applies business rules, writes a model, and formats notification side effects. Refactor the controller to validate HTTP input, call a service with explicit parameters, and map the result into the existing response envelope.", "The same service operation can be tested without an Express response object.", "Authorization identity remains explicit and is not lost in the refactor.", "async function createRoadmap(req, res, next) { try { const roadmap = await roadmapService.createForUser(req.user.id, req.validated.body); return res.status(201).json({ success: true, data: roadmap }); } catch (error) { return next(error); } }", "Pass the authenticated owner and validated body as explicit service arguments.", "Keep status, headers, and response serialization in the controller."],
            ["Hard", "Make side effects best-effort after primary success", "A controller saves a project and then creates a notification. Ensure the project response remains successful if notification creation fails, while logging only safe diagnostic metadata and never creating a notification before the database commit.", "The project is persisted and returns success even if notification service rejects.", "A failed project write creates no notification.", "const project = await projectService.create(input); try { await notificationService.create({ userId: req.user.id, type: 'project', title: 'Project added', link: '/projects' }); } catch (error) { logger.warn({ name: error.name, code: error.code }, 'Notification creation failed'); } return res.status(201).json({ success: true, data: project });", "Place the non-critical side effect after the primary operation succeeds.", "Catch only notification failure locally so it cannot convert a committed project into a failed response."],
            ["Hard", "Return partial batch outcomes accurately", "A controller accepts a batch import where some rows can be created and some rejected. Design a response with per-row outcome, accurate created/rejected counts, and a status policy; never return a single all-success message when part of the batch failed.", "The response identifies every input row and reflects its actual persistence result.", "A database outage does not count unattempted rows as rejected validation rows.", "const outcomes = await importService.processRows(req.user.id, req.validated.rows); const created = outcomes.filter((item) => item.status === 'created').length; const rejected = outcomes.filter((item) => item.status === 'rejected').length; return res.status(rejected ? 207 : 201).json({ success: rejected === 0, data: outcomes, counts: { created, rejected } });", "Track validation rejection separately from operational failure and unattempted work.", "Derive counts from the actual outcome list instead of trusting submitted totals."],
        ]
    },
    Services: {
        hints: ["A service should expose a domain operation with explicit inputs and a predictable result.", "Keep side effects ordered, make transaction requirements explicit, and avoid HTTP response concerns in the service."],
        items: [
            ["Easy", "Extract an owned project lookup", "Write projectService.getOwned(projectId, userId) that queries by both identifiers and returns the project or null. Keep Express request and response objects out of the service signature.", "A matching owner receives their project result.", "A valid project ID belonging to another user returns null from the same query shape.", "async function getOwned(projectId, userId) { return Project.findOne({ _id: projectId, user: userId }); }", "Make identity a required argument and include it in the database predicate.", "Return a documented not-found result rather than constructing an HTTP response."],
            ["Easy", "Normalize a project title in one service", "Create a project service operation that trims a supplied title, rejects a blank value, and persists the normalized title. Ensure the controller does not duplicate the same normalization rule.", "'  Portfolio  ' persists as 'Portfolio'.", "Whitespace-only input rejects before Model.create is called.", "async function createProject(userId, input) { const title = typeof input.title === 'string' ? input.title.trim() : ''; if (!title) throw Object.assign(new Error('Title is required'), { name: 'ValidationError' }); return Project.create({ title, user: userId }); }", "Put the domain rule in one boundary used by every caller.", "Validate before persistence and derive owner from an explicit trusted service argument."],
            ["Medium", "Separate primary writes from notification failure", "A project service saves a project then creates a user notification. Treat notification as non-critical: it must happen only after persistence, its failure must be logged safely, and it must not reject an already-successful project operation.", "A successful create returns the saved project even when notification creation fails.", "A failed database save does not call notificationService.", "async function createProject(userId, input) { const project = await Project.create({ ...input, user: userId }); try { await notificationService.createForUser(userId, { type: 'project', title: 'Project added' }); } catch (error) { logger.warn({ name: error.name, code: error.code }, 'Notification creation failed'); } return project; }", "Place the notification after the primary database write.", "Catch and sanitize only the optional side effect; let the primary persistence error propagate."],
            ["Medium", "Make a service query paginated and deterministic", "Implement listProjects(userId, page, limit) using a bounded page size and newest-first deterministic ordering. Return both the page array and a total count without accepting owner identity from filter input.", "Page results sort by createdAt descending then _id descending.", "A limit above 50 is capped or rejected according to the documented API policy.", "async function listProjects(userId, page, limit) { const safeLimit = Math.min(limit, 50); const filter = { user: userId }; const [data, total] = await Promise.all([Project.find(filter).sort({ createdAt: -1, _id: -1 }).skip((page - 1) * safeLimit).limit(safeLimit), Project.countDocuments(filter)]); return { data, total, page, limit: safeLimit }; }", "Construct the ownership filter internally and apply the same filter to list and count.", "Use a unique sort tie-breaker so consecutive pages are stable for equal timestamps."],
            ["Hard", "Use a transaction for a coupled write", "Creating a course enrollment requires both an enrollment document and a seat counter update to succeed together. Design a MongoDB transaction service operation, including session propagation and cleanup, and explain deployment prerequisites.", "Both records commit together or neither change remains.", "If the second write fails, the enrollment is rolled back.", "async function enroll(userId, courseId) { const session = await mongoose.startSession(); try { let enrollment; await session.withTransaction(async () => { const course = await Course.findOneAndUpdate({ _id: courseId, seatsRemaining: { $gt: 0 } }, { $inc: { seatsRemaining: -1 } }, { new: true, session }); if (!course) throw new Error('No seats available'); [enrollment] = await Enrollment.create([{ user: userId, course: courseId }], { session }); }); return enrollment; } finally { await session.endSession(); } }", "Use a transaction only when both writes form one invariant and the MongoDB deployment supports transactions.", "Pass the session to every participating operation and always end it in finally."],
            ["Hard", "Make a retried service operation idempotent", "An import service may be called twice after a timeout. Use a unique owner-scoped import key and request hash so identical retries return the original result while a changed payload with the same key conflicts.", "Same owner/key/hash returns the stored result without duplicate inserts.", "The same key and owner with a different hash produces a conflict.", "async function importOnce(userId, key, hash, run) { const prior = await ImportRun.findOne({ user: userId, key }); if (prior) { if (prior.requestHash !== hash) throw new Error('Idempotency conflict'); if (prior.status === 'complete') return prior.result; } const record = await ImportRun.create({ user: userId, key, requestHash: hash, status: 'running' }); const result = await run(); await ImportRun.updateOne({ _id: record.id }, { $set: { status: 'complete', result } }); return result; }", "Scope the key to the authenticated account and bind it to normalized input.", "Persist completion and define recovery for a process crash while the run is marked running."],
        ]
    },
    Validation: {
        hints: ["Treat every request as untrusted and validate type, shape, range, length, and allowed fields at the server boundary.", "Use normalized validated output, not the original request object, in the database query or write."],
        items: [
            ["Easy", "Validate a project title at the API boundary", "Define a Joi schema for a project title that trims whitespace, requires at least two characters, and caps length at 120. The controller should use the normalized validation result, not req.body directly.", "'  API portal  ' is accepted as 'API portal'.", "A one-character or whitespace-only title is rejected with a 400 response.", "const schema = Joi.object({ title: Joi.string().trim().min(2).max(120).required() }).unknown(false);\nconst { error, value } = schema.validate(req.body, { abortEarly: false, convert: true });\nif (error) return res.status(400).json({ success: false, message: 'Invalid project title' });\nreq.validated = value;", "Enable trimming and length constraints in the server schema.", "Reject unknown input, return a safe static message, and pass only the normalized value onward."],
            ["Easy", "Reject object-shaped scalar query values", "A job endpoint expects role as one string no longer than 100 characters. Reject repeated parameters, arrays, objects, and bracket-form variants instead of coercing them or ignoring them.", "?role=Designer passes as a scalar string.", "?role[]=Designer, ?role[x]=Designer, and repeated role values return 400.", "function validateRoleQuery(req, res, next) { const keys = Object.keys(req.query); if (keys.some((key) => /^role\\[/.test(key)) || Array.isArray(req.query.role) || typeof req.query.role === 'object' || (req.query.role != null && (typeof req.query.role !== 'string' || req.query.role.length > 100))) return res.status(400).json({ success: false, message: 'Invalid role query' }); return next(); }", "Inspect parsed keys for bracket variants in addition to checking the expected property.", "Treat a repeated scalar as ambiguous input and reject it before query construction."],
            ["Medium", "Allowlist an update payload", "A profile PATCH accepts name, location, and bio only. Validate each field's type and length, reject unknown keys such as role or userId, and preserve omitted fields instead of replacing them with empty values.", "A payload containing only bio updates only bio.", "An unknown userId field fails validation and cannot change ownership.", "const schema = Joi.object({ name: Joi.string().trim().min(1).max(100), location: Joi.string().trim().max(120), bio: Joi.string().trim().max(1000) }).min(1).unknown(false);\nconst { error, value } = schema.validate(req.body, { abortEarly: false, convert: true });", "Use optional schema fields so omission differs from an explicitly supplied value.", "Reject unknown fields instead of spreading the request into a model update."],
            ["Medium", "Validate a bounded date range", "An activity report accepts start and end date strings. Validate strict ISO dates, require start no later than end, and cap the interval to 366 days before using it in a database query.", "A 30-day valid range proceeds.", "An invalid date, reversed range, or 367-day interval returns 400.", "function validateRange(start, end) { const from = new Date(start); const to = new Date(end); if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(start) || !/^\\d{4}-\\d{2}-\\d{2}$/.test(end) || !Number.isFinite(from.getTime()) || !Number.isFinite(to.getTime()) || from > to || to - from > 366 * 86400000) throw new Error('Invalid date range'); return { from, to }; }", "Check the lexical ISO shape as well as whether JavaScript parsed a valid date.", "Compare the range in milliseconds and enforce the maximum before querying."],
            ["Hard", "Validate a nested filter without Mongo operators", "An endpoint accepts a filter with status and location strings but never arbitrary MongoDB expressions. Define an allowlist schema that rejects arrays, nested objects, unknown keys, and keys beginning with dollar signs.", "{status:'open',location:'Pune'} passes.", "{status:{$ne:'closed'}} and unknown nested keys are rejected before the model call.", "const filterSchema = Joi.object({ status: Joi.string().valid('open', 'closed'), location: Joi.string().trim().max(100) }).unknown(false);\nconst { error, value } = filterSchema.validate(req.query, { abortEarly: false, convert: false });\nif (error || Object.values(value || {}).some((item) => typeof item !== 'string')) throw new Error('Invalid filter');", "Do not pass request query objects directly to a database API.", "Reject unknown properties and enforce scalar strings on the validated output."],
            ["Hard", "Separate validation from ownership authorization", "A request contains a syntactically valid document ID that belongs to another user. Explain why schema validation is insufficient and implement the query boundary using the authenticated user ID and validated ID together.", "A user's own ID can be queried successfully.", "A valid ID owned by another account returns no record and reveals no file metadata.", "const { error, value } = documentIdSchema.validate(req.params.id);\nif (error) return res.status(400).json({ success: false, message: 'Invalid document id' });\nconst document = await Document.findOne({ _id: value, user: req.user.id });", "Validation proves the identifier's shape, not permission to access the resource.", "Combine the normalized ID and trusted authenticated owner in the database predicate."],
        ]
    },
    "Error Handling": {
        hints: ["Distinguish expected client failures from unexpected infrastructure failures.", "Log only sanitized diagnostics and preserve the first failure when cleanup or response handling also fails."],
        items: [
            ["Easy", "Map a missing record to a safe 404", "A service returns null for an unknown project. Add controller behavior that returns a stable 404 envelope and does not return database details or a 200 response containing null.", "Missing project produces status 404 and a safe message.", "An existing record still uses the unchanged success envelope.", "if (!project) return res.status(404).json({ success: false, message: 'Project not found' });\nreturn res.status(200).json({ success: true, data: project });", "Handle the documented absence result before constructing the success response.", "Do not expose whether an inaccessible cross-user record exists if the API uses a uniform not-found policy."],
            ["Easy", "Keep client errors distinct from server errors", "An Express route can throw a known ValidationError or an unexpected Mongo error. Map validation to a safe 400 and return a generic 500 for unexpected failures while logging only error name and code.", "Validation remains 400; Mongo failure returns 'Internal server error'.", "The stack, query, database host, and request body do not appear in the response or logs.", "function errorHandler(error, req, res, next) { if (error.name === 'ValidationError') return res.status(400).json({ success: false, message: 'Invalid request' }); logger.error({ name: error.name, code: error.code, requestId: req.id }); return res.status(500).json({ success: false, message: 'Internal server error' }); }", "Recognize only known safe client errors.", "Return a generic unexpected error and keep sanitized diagnostic fields server-side."],
            ["Medium", "Preserve the primary error during cleanup", "A service opens a temporary file, writes data, and removes the file after failure. If cleanup also fails, preserve the original write error as the primary rejection and attach cleanup diagnostics without leaking the path to clients.", "Write failure remains the rejected cause even when removeFile also fails.", "A successful write and cleanup returns the write result.", "async function writeTemporary(writeFile, removeFile) { let primary; try { return await writeFile(); } catch (error) { primary = error; throw error; } finally { try { await removeFile(); } catch (cleanupError) { logger.warn({ name: cleanupError.name, code: cleanupError.code }, 'Temporary cleanup failed'); if (!primary) throw cleanupError; } } }", "Track whether the main operation already failed before deciding which error to propagate.", "Keep cleanup diagnostics sanitized and avoid including local file paths in user responses."],
            ["Medium", "Add a safe request correlation ID", "An endpoint fails intermittently in production. Add a request ID to the response and structured server log so support can correlate a report without logging the user's submitted document or authorization token.", "The response and error log include the same opaque request ID.", "Logs omit request bodies, token headers, and extracted document text.", "logger.error({ requestId: req.id, route: req.path, method: req.method, name: error.name, code: error.code }, 'Document request failed');\nres.status(500).json({ success: false, message: 'Internal server error', requestId: req.id });", "Use a server-generated ID and safe route metadata as correlation context.", "Never use private input content as the correlation value."],
            ["Hard", "Handle errors after streaming begins", "A download controller begins piping a private file, then the file stream fails after headers are sent. Ensure the error handler does not attempt a JSON response over the stream and terminates the connection safely.", "Before headers, a safe error response is possible.", "After headers, the stream is destroyed and the failure is logged without ERR_HTTP_HEADERS_SENT.", "function handleStreamError(error, req, res) { logger.error({ requestId: req.id, name: error.name, code: error.code }, 'Download stream failed'); if (res.headersSent) return res.destroy(error); return res.status(500).json({ success: false, message: 'Unable to download file' }); }", "Check headersSent before writing a response body.", "Once streaming starts, terminate the stream rather than sending a second response format."],
            ["Hard", "Design safe error taxonomy for an upload pipeline", "A private document upload can fail validation, ownership checks, disk storage, parsing, or an AI provider call. Define which failures are 4xx versus 5xx, what the client may see, and which sanitized fields are useful in logs.", "Invalid type/size remains a client error; disk or provider failures are generic server errors.", "Logs never include file contents, personal filenames, credentials, or extracted text.", "const publicErrors = { INVALID_FILE: [400, 'Unsupported file'], TOO_LARGE: [400, 'File exceeds the size limit'], PROVIDER_FAILURE: [503, 'Service temporarily unavailable'] };\nlogger.error({ requestId: req.id, code: error.code, name: error.name }, 'Upload processing failed');", "Map known domain codes deliberately, not by exposing arbitrary error.message.", "Separate client-safe text from server diagnostics and include only a correlation ID."],
        ]
    },
    "File Uploads": {
        hints: ["Multipart metadata is untrusted; use limits at the parser and validate bytes before extraction.", "Private storage needs generated names, owner-scoped metadata, and cleanup for every rejected path."],
        items: [
            ["Easy", "Limit an upload to one expected field", "Configure Multer for exactly one file in field 'document' and a 10 MiB limit. Convert unexpected field or multiple-file errors into a controlled 400 response before the controller executes.", "One document field under the limit reaches the controller as req.file.", "A second file, wrong field, or oversized file is rejected at the middleware layer.", "const uploadOne = multer({ limits: { fileSize: 10 * 1024 * 1024, files: 1 } }).single('document');\nrouter.post('/', (req, res, next) => uploadOne(req, res, (error) => error ? res.status(400).json({ success: false, message: 'Invalid upload' }) : next()), controller);", "Set the file count and size limits in Multer rather than buffering extra files first.", "Handle Multer errors explicitly and preserve a predictable req.file contract."],
            ["Easy", "Reject an unsupported extension with a useful message", "An upload form supports PDF, TXT, DOC, and DOCX only. Inspect the selected filename extension before submission for fast feedback, while keeping server validation authoritative and not adding image support.", "A JPEG selection receives a clear supported-formats message.", "Renaming a JPEG to .pdf still fails server content validation.", "const allowed = new Set(['.pdf', '.txt', '.doc', '.docx']);\nfunction isSupportedName(filename) { return allowed.has(path.extname(filename).toLowerCase()); }", "Client checks improve feedback but do not establish actual file type.", "Repeat validation on the server using content signatures or structural checks."],
            ["Medium", "Verify a DOCX container before extraction", "A client claims a DOCX MIME type and extension. Validate that the bytes form a ZIP archive containing required Office document entries such as [Content_Types].xml and word/document.xml before passing the file to the parser.", "A valid DOCX with required entries proceeds to extraction.", "A random ZIP or renamed JPEG is rejected and removed from temporary storage.", "const entries = await readZipEntryNames(filePath);\nif (!entries.has('[Content_Types].xml') || !entries.has('word/document.xml')) throw new UploadValidationError('Invalid DOCX');", "MIME and extension are hints; inspect the container's structure.", "Reject malformed content before extraction and remove temporary files on failure."],
            ["Medium", "Store private files under generated names", "A user's uploaded resume must not be addressable through a public static directory or original filename. Design storage using a generated key, private directory permissions, and a database record scoped to the authenticated owner.", "The metadata stores a generated key, not a path derived from the user's filename.", "Guessing another user's document ID or path cannot download the file.", "const storageKey = crypto.randomUUID();\nconst destination = path.join(privateUploadRoot, storageKey);\nawait fs.writeFile(destination, bytes, { flag: 'wx', mode: 0o600 });\nawait Document.create({ storageKey, user: req.user.id, originalName: sanitizedDisplayName });", "Keep the storage directory outside public static mounts and generate unguessable server keys.", "Authorize every download by querying both document ID and authenticated owner."],
            ["Hard", "Clean up partial storage after parse failure", "An upload is written to a private temporary path, but PDF parsing fails after the bytes are stored. Ensure parser failure removes the temporary file and prevents a persistent document record or success response.", "Valid content is parsed, moved to final private storage, and then recorded.", "Invalid content leaves neither a database record nor a temporary file.", "const temporaryPath = await storeTemporary(file);\ntry { const extracted = await extract(temporaryPath); const storageKey = await promotePrivate(temporaryPath); return await Document.create({ user: req.user.id, storageKey, extracted }); } catch (error) { await fs.rm(temporaryPath, { force: true }); throw error; }", "Do not create the durable metadata record until validation and extraction succeed.", "Put cleanup in a failure-safe path and make removal idempotent."],
            ["Hard", "Prevent archive expansion abuse", "A DOCX file is below the upload byte limit but expands to an enormous ZIP payload with thousands of entries. Design extraction limits for total uncompressed bytes, entry count, and path traversal; reject before consuming unbounded memory or writing outside the extraction directory.", "A normal small document remains processable.", "Excessive entries, expansion ratio, or ../ entry paths are rejected safely.", "for (const entry of zip.entries) { if (entryCount++ >= MAX_ENTRIES || (totalBytes += entry.uncompressedSize) > MAX_UNCOMPRESSED_BYTES) throw new UploadValidationError('Archive limits exceeded'); if (path.isAbsolute(entry.name) || entry.name.split('/').includes('..')) throw new UploadValidationError('Unsafe archive path'); }", "Compressed file size alone does not bound decompression work.", "Enforce limits before extraction and validate normalized entry paths against traversal."],
        ]
    },
    Authentication: {
        hints: ["Authentication establishes who the caller is; it does not by itself grant access to every resource.", "Treat tokens as secrets, validate them in trusted middleware, and separate 401 identity failure from network failure."],
        items: [
            ["Easy", "Require an authenticated identity", "Write Express middleware that accepts a Bearer token, verifies it through the configured verifier, and attaches only the verified subject to req.user. Missing or malformed credentials must stop before the protected controller.", "A valid verified token reaches the handler with req.user.id.", "A userId query parameter without a token cannot reach the handler.", "async function requireAuth(req, res, next) { const header = req.get('authorization') || ''; const match = /^Bearer (.+)$/.exec(header); if (!match) return res.status(401).json({ success: false, message: 'Authentication required' }); try { const claims = await verifyToken(match[1]); req.user = { id: claims.sub }; return next(); } catch { return res.status(401).json({ success: false, message: 'Authentication required' }); } }", "Take identity from verified claims, never from query or body fields.", "Return immediately after sending 401 and do not attach unverified claims."],
            ["Easy", "Distinguish session expiry from offline state", "A frontend service receives a 401 from a protected endpoint or a network rejection. Return distinct states so the UI can ask the user to sign in for 401 but offer retry for connectivity failures.", "401 renders a session-expired state.", "A rejected network request does not clear the user's authenticated session.", "async function loadPrivate(api) { try { return { status: 'success', data: await api() }; } catch (error) { if (error.status === 401) return { status: 'unauthenticated' }; return { status: 'network-error' }; } }", "Inspect an HTTP status only when a response exists.", "Keep authentication invalidation separate from transient transport failure."],
            ["Medium", "Issue a minimal access token", "Design a JWT payload for a signed-in user that carries a stable subject, issuer, audience, and expiry but excludes password, email, and mutable admin permissions. Explain where current role authorization should be read.", "The verifier can identify the subject and validate audience and lifetime.", "A role change takes effect according to current server-side authorization rather than a stale long-lived claim.", "const token = jwt.sign({ sub: user.id, iss: 'career-os', aud: 'career-os-api' }, signingKey, { expiresIn: '15m', algorithm: 'HS256' });", "Include only claims required for identity and validation.", "Load sensitive or frequently changing authorization data from trusted server state."],
            ["Medium", "Protect password verification and response", "Implement a login service boundary that validates email and password strings, compares the submitted password using the stored password hash, and returns only a token and safe public user fields. Never return or log the hash.", "A valid account receives a token and allowlisted public profile.", "Invalid credentials produce the same generic response whether email or password was wrong.", "async function login(email, password) { const user = await User.findOne({ email: normalizeEmail(email) }); if (!user || !(await bcrypt.compare(password, user.passwordHash))) throw new AuthenticationError('Invalid credentials'); return { token: signAccessToken(user.id), user: { id: user.id, name: user.name } }; }", "Use a password hashing comparison, not plaintext equality.", "Keep the response allowlisted and use a generic credential failure."],
            ["Hard", "Rotate refresh tokens and detect replay", "Design a refresh-token rotation flow in which each valid refresh token is consumed once and replaced by a new one. Store only a token hash, detect reuse of an already-rotated token, and revoke the affected session family.", "A valid token rotates to a new token and the old hash becomes consumed.", "Reusing the old token is detected and does not mint another valid access token.", "const tokenHash = hashToken(presentedToken); const record = await RefreshSession.findOneAndUpdate({ tokenHash, status: 'active', expiresAt: { $gt: new Date() } }, { $set: { status: 'rotated', rotatedAt: new Date() } }, { new: true }); if (!record) throw new AuthenticationError('Refresh token invalid'); const replacement = await issueRefreshToken(record.userId, record.familyId);", "Make token consumption atomic so concurrent refresh calls cannot both succeed.", "Store a hash, track token family, and revoke the family when rotation replay is detected."],
            ["Hard", "Handle logout across active sessions", "A user can sign in on several devices and chooses to revoke one session or all sessions. Design server-side session identifiers and logout behavior that invalidates the intended refresh credentials while short-lived access tokens expire safely.", "Single-device logout revokes only that session family.", "Logout-all invalidates every active refresh session without storing raw token strings.", "await RefreshSession.updateMany({ user: req.user.id, ...(sessionId ? { sessionId } : {}) }, { $set: { status: 'revoked', revokedAt: new Date() } });\nres.status(204).end();", "A stateless access token alone cannot be instantly revoked without additional server state.", "Scope revocation by authenticated owner and use stored token hashes or session records."],
        ]
    },
    Authorization: {
        hints: ["Authorize each object operation against the authenticated principal and trusted server-side roles.", "Test horizontal and vertical access separately; a hidden frontend action is not a security boundary."],
        items: [
            ["Easy", "Scope a project query to its owner", "Implement a service query for one project using both projectId and authenticated userId. Return null when no owned record matches so another account's valid identifier is not disclosed.", "Owner A can read A's project.", "Owner B using the same project ID receives no record.", "async function getOwnedProject(projectId, userId) { return Project.findOne({ _id: projectId, user: userId }); }", "Combine object identity and owner identity in the database query.", "Use a uniform not-found policy for absent and not-owned records when existence is sensitive."],
            ["Easy", "Enforce an admin-only operation on the server", "Add role-check middleware for POST /api/jobs using the verified authenticated user. Keep frontend button visibility as presentation only and return 401 for no identity versus 403 for an authenticated non-admin.", "An admin proceeds to job creation.", "Changing a client-side role field does not grant access; a normal user receives 403.", "function requireAdmin(req, res, next) { if (!req.user) return res.status(401).json({ success: false, message: 'Authentication required' }); if (req.user.role !== 'admin') return res.status(403).json({ success: false, message: 'Forbidden' }); return next(); }\nrouter.post('/jobs', requireAuth, requireAdmin, createJob);", "Use role data populated by trusted authentication middleware.", "Apply the check to the route before any creation side effect."],
            ["Medium", "Authorize a document download without public paths", "A private document is stored on disk. For GET /documents/:id/download, find its metadata using both ID and req.user.id, resolve a generated storage key beneath the private root, and stream it only after authorization.", "The owner downloads their record through the authenticated route.", "Another user's ID and a path traversal string cannot read a file.", "const doc = await Document.findOne({ _id: req.params.id, user: req.user.id }); if (!doc) return res.status(404).json({ success: false, message: 'Document not found' }); const filePath = path.resolve(privateRoot, doc.storageKey); if (!filePath.startsWith(`${path.resolve(privateRoot)}${path.sep}`)) throw new Error('Invalid storage key'); return res.download(filePath, doc.safeDownloadName);", "Never accept a filesystem path from the request or serve the private directory statically.", "Authorize metadata first and constrain the resolved generated key to the private root."],
            ["Medium", "Avoid mass assignment of role fields", "A profile PATCH lets users update name and location, but a malicious client submits role='admin'. Build an allowlisted update and reject or ignore protected fields according to a clear validation contract.", "Name and location can be updated.", "The role remains unchanged and the request cannot elevate privileges.", "const { name, location } = req.validated.body; await User.updateOne({ _id: req.user.id }, { $set: { name, location } });", "Do not spread arbitrary request bodies into a model update.", "Build the update from explicit user-editable properties only."],
            ["Hard", "Prevent cross-tenant aggregation leaks", "An analytics endpoint groups project counts by status. Ensure every aggregation stage begins from the authenticated tenant/user scope and no later lookup can reintroduce records from other tenants.", "Counts include only records belonging to the current tenant.", "A project ID reference from another tenant is filtered before aggregation output.", "const rows = await Project.aggregate([{ $match: { tenant: new mongoose.Types.ObjectId(req.user.tenantId) } }, { $group: { _id: '$status', count: { $sum: 1 } } }]);", "Put the trusted tenant match before grouping and joins.", "Review every lookup and unwind stage for the same tenant boundary."],
            ["Hard", "Separate role permissions from ownership", "An admin may review documents but only the owner may delete them unless a documented moderation permission applies. Design a policy that checks both role and operation, and ensure ordinary admin status does not accidentally bypass ownership for every action.", "The owner can delete their document; admin read access follows the explicit policy.", "A generic admin flag does not automatically permit every destructive operation.", "function canDeleteDocument(user, document) { return String(user.id) === String(document.user) || user.permissions?.includes('documents:delete:any') === true; }\nconst allowed = canDeleteDocument(req.user, document);", "Model permissions by action instead of assuming one role grants all operations.", "Require an explicit server-side permission for cross-owner destructive access."],
        ]
    },
    JWT: {
        hints: ["JWTs are signed, not encrypted; claims can be read by anyone holding the token.", "Pin verification algorithms and validate signature, issuer, audience, and lifetime using trusted configuration."],
        items: [
            ["Easy", "Verify an access-token signature", "Write a verifier that accepts only the application's configured signing algorithm and expected issuer/audience. Reject malformed, expired, and invalid-signature tokens before attaching identity to req.user.", "A correctly signed token with expected iss and aud yields a subject.", "A token with a wrong audience or expired exp is rejected.", "function verifyAccessToken(token) { return jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'], issuer: 'career-os', audience: 'career-os-api' }); }", "Verification options should be explicit, not inferred from an attacker-controlled header.", "Only attach claims after the library has validated signature and registered constraints."],
            ["Easy", "Keep private data out of JWT claims", "A developer proposes putting email, resume text, and role in a JWT because it avoids database reads. Redesign the claims to include only stable subject and bounded expiry; explain that base64url is not encryption.", "The payload contains subject and standard timing/issuer claims only.", "Resume contents and secrets are absent even though the token can be decoded by the client.", "const payload = { sub: user.id, iss: 'career-os', aud: 'career-os-api' };\nconst token = jwt.sign(payload, signingKey, { expiresIn: '15m', algorithm: 'HS256' });", "Treat every JWT payload as readable by its holder.", "Keep private profile and document data behind owner-authorized APIs."],
            ["Medium", "Validate subject before using it as an owner ID", "A JWT verifies cryptographically but its sub claim is missing or not a valid user identifier. Validate the claim's type and expected format before constructing owner-scoped database queries.", "A valid subject is normalized and attached to req.user.id.", "A token with missing, array-valued, or malformed sub receives 401.", "function identityFromClaims(claims) { if (typeof claims.sub !== 'string' || !/^[a-f0-9]{24}$/i.test(claims.sub)) throw new Error('Invalid subject'); return { id: claims.sub }; }", "A valid signature does not guarantee every application-specific claim has the required shape.", "Validate identity fields before using them in a database filter."],
            ["Medium", "Use key IDs during signing-key rotation", "Two trusted JWT signing keys overlap during a controlled rotation. Design verification using a server-owned key map keyed by kid, reject unknown kid values, and pin each key to its permitted algorithm.", "Tokens signed by either configured active key validate during overlap.", "An attacker-provided kid URL or unknown key is rejected without fetching external material.", "const keys = { current: { key: currentKey, algorithm: 'HS256' }, previous: { key: previousKey, algorithm: 'HS256' } };\nconst header = jwt.decode(token, { complete: true })?.header; const entry = keys[header?.kid]; if (!entry || header.alg !== entry.algorithm) throw new Error('Invalid token'); return jwt.verify(token, entry.key, { algorithms: [entry.algorithm], issuer: 'career-os', audience: 'career-os-api' });", "Select only from a local trusted key map; never fetch a key URL from the token.", "Verify the algorithm against the key's configured policy and continue validating issuer and audience."],
            ["Hard", "Design refresh-token replay detection", "A long-lived refresh JWT is rotated after each use. Describe the server-side session record needed to detect reuse of an old token, revoke the token family, and avoid storing raw refresh tokens.", "The presented token is hashed and matched to one active session record before atomic rotation.", "A replayed rotated token revokes its family and cannot mint a new access token.", "const presentedHash = crypto.createHash('sha256').update(token).digest('hex');\nconst session = await RefreshSession.findOneAndUpdate({ tokenHash: presentedHash, status: 'active' }, { $set: { status: 'rotated', rotatedAt: new Date() } }, { new: true });\nif (!session) await revokeFamilyForReplay(presentedHash);", "A signed JWT alone cannot reveal that it has already been used; maintain server-side rotation state.", "Store a hash, update atomically, and define how replay affects the session family."],
            ["Hard", "Choose revocation strategy for a compromised access token", "An access token with a one-hour lifetime is stolen. Compare short lifetimes, session version checks, and a denylist; recommend a design according to required revocation latency, database availability, and request cost, without logging token values.", "The recommendation states the revocation latency and operational tradeoffs.", "The design does not claim immediate revocation from a purely stateless verifier.", "// Example session-version check: token carries a sessionVersion; compare it with the current user/session record before protected access.\nif (claims.sessionVersion !== user.sessionVersion) throw new AuthenticationError('Session revoked');", "Write the required revocation latency first, then choose state and lookup cost that meet it.", "Acknowledge that stateless validation cannot instantly revoke a token without a server-side check."],
        ]
    },
};

const slug = (value) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

export const BACKEND_MORE_EXERCISES = Object.fromEntries(Object.entries(backendScenarios).map(([topic, data]) => [
    topic,
    data.items.map(([difficulty, title, problem, expected, edgeCase, solutionCode], index) => {
        const fullProblem = `${problem} State the accepted inputs, implement or specify the required behavior, and verify both the representative result and the edge condition.`;
        return {
            id: `fs-backend-${slug(topic)}-${difficulty.toLowerCase()}-${index + 2}-v1`,
            career: "Full Stack Developer",
            phase: "Backend Development",
            topic,
            title,
            difficulty,
            estimatedTime: difficulty === "Easy" ? "25–35 minutes" : difficulty === "Medium" ? "40–55 minutes" : "55–75 minutes",
            kind: "coding",
            language: "Node.js / Express",
            problemStatement: fullProblem,
            simplerProblem: `Implement the normal case first: ${expected}`,
            learningObjectives: [
                `Apply ${topic} to the specific server-side scenario in the prompt.`,
                "Define a clear input/output contract and preserve authentication, validation, and error semantics where relevant.",
                "Verify a representative case and a failure or boundary case before reporting success."
            ],
            requirements: [
                `Implement the behavior described for ${topic} without trusting unvalidated client input.`,
                "Keep ownership, authorization, or resource limits explicit where the scenario requires them.",
                "Return a truthful result: rejected work must not be reported as persisted or successful."
            ],
            examples: [
                { input: problem, output: expected, explanation: `This example demonstrates the primary ${topic} contract in a realistic server feature.` },
                { input: `Boundary case: ${edgeCase}`, output: edgeCase, explanation: "This case checks the failure, range, or boundary behavior required by the scenario." }
            ],
            tests: [
                { name: "Primary scenario", input: problem, expected },
                { name: "Boundary scenario", input: edgeCase, expected: edgeCase }
            ],
            hints: data.hints,
            conceptsToReview: [topic, "Request boundaries", "Safe error handling"],
            prerequisites: ["JavaScript functions", "HTTP request lifecycle", "Basic asynchronous code"],
            approach: `Treat this as a ${topic} contract rather than a happy-path-only task. Validate the inputs at the boundary, keep trusted identity and server-owned data separate from client values, and perform the operation through one clear service or middleware responsibility. Decide what the caller observes for both the normal case and the required edge case.`,
            walkthrough: `For the primary scenario, the expected outcome is: ${expected} Then trace the edge case: ${edgeCase} The reference below demonstrates the important control flow and should be paired with tests for the endpoint's status, response envelope, and any persistence or cleanup guarantee described by the prompt.`,
            solutionCode,
            solutionLines: [
                `Validate the ${topic} inputs before using them in a query, side effect, or response.`,
                "Perform the operation with explicit ownership, resource bounds, and failure handling required by the problem.",
                "Verify the normal result and the edge case; preserve a safe diagnostic path without exposing secrets."
            ],
            commonMistakes: [
                "Trusting a client-provided identity, file type, query object, or role instead of a server-verified value.",
                "Returning success before the primary operation is confirmed or after a required validation failed.",
                "Leaking raw exception details, credentials, filesystem paths, or private content to the client or logs."
            ],
            followUp: `Add one additional production constraint to ${title.toLowerCase()} and update the test cases without changing its existing response contract.`,
            completionCriteria: [
                `The primary scenario produces the stated outcome: ${expected}`, 
                `The edge case is handled explicitly: ${edgeCase}`, 
                `The solution keeps the ${topic} boundary secure, bounded, and consistent with the documented API behavior.`
            ],
            starterCode: `// ${topic}: ${title}\n// Implement the contract in the problem statement.\nasync function handle(input, context) {\n  // validate, perform the operation, and return a truthful result\n}`
        };
    })
]));
